.ms-chat-input-area {
 display: flex;
 align-items: center;
 gap: 8px;
 padding: 12px 16px;
 background: rgb(var(--now-color_background--primary, 255, 255, 255));
 border-top: 1px solid rgb(var(--now-container-card--border-color, 218, 220, 224));
 flex-shrink: 0;
}

.ms-chat-input {
 flex: 1;
 padding: 10px 14px;
 border: 1px solid rgb(var(--now-container-card--border-color, 218, 220, 224));
 border-radius: 24px;
 font-size: 0.8125rem;
 font-family: inherit;
 background: rgb(var(--now-color_background--secondary, 243, 243, 243));
 color: rgb(var(--now-color_text--primary, 16, 23, 26));
 outline: none;
 transition: border-color 0.2s, box-shadow 0.2s;
}

.ms-chat-input:focus {
 border-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 box-shadow: 0 0 0 2px rgba(0, 128, 163, 0.12);
 background: rgb(var(--now-color_background--primary, 255, 255, 255));
}

.ms-chat-input:disabled {
 opacity: 0.6;
 cursor: not-allowed;
}

.ms-chat-send-btn {
 width: 40px;
 height: 40px;
 border-radius: 50%;
 border: none;
 background: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 color: #fff;
 display: flex;
 align-items: center;
 justify-content: center;
 cursor: pointer;
 transition: background 0.2s, transform 0.2s;
 flex-shrink: 0;
}

.ms-chat-send-btn:hover:not(:disabled) {
 background: #006d8a;
 transform: scale(1.05);
}

.ms-chat-send-btn:disabled {
 opacity: 0.4;
 cursor: not-allowed;
}

/* ========================================
 Chat Widget - Interactive Options
 ======================================== */

/* Clickable option buttons within chat */
.ms-chat-options {
 display: flex;
 flex-wrap: wrap;
 gap: 8px;
 padding: 8px 0 4px 0;
 margin-left: 4px;
}

.ms-chat-option-btn {
 padding: 8px 14px;
 border-radius: 20px;
 border: 1px solid rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 background: rgb(var(--now-color_background--primary, 255, 255, 255));
 color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 font-size: 0.75rem;
 font-weight: 500;
 cursor: pointer;
 transition: all 0.2s;
 white-space: nowrap;
 font-family: inherit;
}

.ms-chat-option-btn:hover:not(:disabled) {
 background: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 color: #fff;
 transform: translateY(-1px);
 box-shadow: 0 2px 8px rgba(0, 128, 163, 0.25);
}

.ms-chat-option-btn:disabled {
 opacity: 0.5;
 cursor: not-allowed;
 border-color: rgb(var(--now-container-card--border-color, 218, 220, 224));
 color: rgb(var(--now-color_text--tertiary, 117, 122, 126));
}

/* Location sharing button */
.ms-chat-location-btn {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 padding: 10px 18px;
 border-radius: 24px;
 border: none;
 background: linear-gradient(135deg, #28a745, #20c997);
 color: #fff;
 font-size: 0.8125rem;
 font-weight: 600;
 cursor: pointer;
 transition: all 0.2s;
 font-family: inherit;
 box-shadow: 0 2px 8px rgba(40, 167, 69, 0.3);
}

.ms-chat-location-btn:hover:not(:disabled) {
 transform: translateY(-1px);
 box-shadow: 0 4px 12px rgba(40, 167, 69, 0.4);
}

.ms-chat-location-btn:active:not(:disabled) {
 transform: translateY(0);
}

.ms-chat-location-btn:disabled {
 opacity: 0.5;
 cursor: not-allowed;
 box-shadow: none;
}

/* ========================================
 Chat Widget - ETA Result Card
 ======================================== */

.ms-chat-result-card {
 background: rgb(var(--now-color_background--primary, 255, 255, 255));
 border: 1px solid rgb(var(--now-container-card--border-color, 218, 220, 224));
 border-radius: 12px;
 margin: 8px 0 4px 4px;
 overflow: hidden;
 box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
