","import React, { useState } from "react";
import { Button } from "@servicenow/react-components/Button";

interface Props {
 navigate: (view: string, extras?: { type?: string; id?: string }) => void;
 issueType: string | null;
}

export default function IssueFormScreen({ navigate, issueType }: Props) {
 const [submitted, setSubmitted] = useState(false);
 const [route, setRoute] = useState("");
 const [description, setDescription] = useState("");

 const typeLabel = (issueType || "other").replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());

 if (submitted) {
 return (
 <div className="ms-screen">
 <div className="ms-success-container">
 <div className="ms-success-icon">✅</div>
 <h2 className="ms-success-title">Issue Reported!</h2>
 <p className="ms-success-text">
 Your {typeLabel} report has been submitted successfully. Reference: #ISS-{Math.floor(Math.random() * 900) + 100}
 </p>
 <Button label="Back to Home" onClick={() => navigate("home")} />
 </div>
 </div>
 );
 }

 return (
 <div className="ms-screen">
 <div className="ms-page-header">
 <button className="ms-back-btn" onClick={() => navigate("report")}>
 <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
 <path d="M19 12H5M12 19l-7-7 7-7" />
 </svg>
 </button>
 <h1 className="ms-page-title">Report: {typeLabel}</h1>
 </div>

 <div className="ms-form">
 <div className="ms-form-group">
 <label className="ms-label">Bus Route</label>
 <select className="ms-select" value={route} onChange={(e) => setRoute(e.target.value)}>
 <option value="">Select a route...</option>
 <option value="42">Route 42 — Campus Express</option>
 <option value="15">Route 15 — North Loop</option>
 <option value="7">Route 7 — Downtown Shuttle</option>
 <option value="23">Route 23 — Medical Center</option>
 </select>
 </div>

 <div className="ms-form-group">
 <label className="ms-label">Date & Time of Incident</label>
 <input className="ms-input" type="datetime-local" />
 </div>

 <div className="ms-form-group">
 <label className="ms-label">Description</label>
 <textarea
 className="ms-textarea"
 placeholder="Describe the issue in detail..."
 rows={4}
 value={description}
 onChange={(e) => setDescription(e.target.value)}
 />
 </div>

 <div className="ms-form-group">
 <label className="ms-label">Severity</label>
 <select className="ms-select">
 <option value="low">Low — Minor inconvenience</option>
 <option value="medium">Medium — Significant issue</option>
 <option value="high">High — Safety concern</option>
 </select>
 </div>

 <Button label="Submit Report" onClick={() => setSubmitted(true)} />
 </div>
 </div>
 );
}
