","import React, { useState, useRef, useEffect } from "react";

/* ─── Types ─── */
interface Message {
 id: number;
 text: string;
 sender: "bot" | "user";
 options?: OptionItem[];
 resultCard?: ResultCard;
 locationBtn?: boolean;
}

interface OptionItem {
 label: string;
 value: string;
}

interface ResultCard {
 caseNumber: string;
 etaResponse: string;
 bus: string;
 route: string;
 stop: string;
}

interface BusDelayState {
 step: "idle" | "select_bus" | "select_route" | "select_stop" | "describe" | "location" | "submitting" | "result";
 busId: string;
 busLabel: string;
 routeId: string;
 routeLabel: string;
 stopId: string;
 stopLabel: string;
 description: string;
 latitude: string;
 longitude: string;
}

/* ─── Static suggestions ─── */
const SUGGESTIONS = [
 "Bus Delay",
 "Bus Schedule",
 "Track My Bus",
 "Bus Pass Status",
 "Lost & Found",
];

/* ─── API helpers ─── */
const API_HEADERS = (): Record<string, string> => ({
 "Content-Type": "application/json",
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck || "",
});

async function fetchTableRecords(table: string, query?: string): Promise<any[]> {
 let url = `/api/now/table/${table}?sysparm_display_value=all&sysparm_limit=50`;
 if (query) url += `&sysparm_query=${encodeURIComponent(query)}`;
 const res = await fetch(url, { headers: API_HEADERS() });
 const json = await res.json();
 return json.result || [];
}

async function createRecord(table: string, body: Record<string, string>): Promise<any> {
 const res = await fetch(`/api/now/table/${table}`, {
 method: "POST",
 headers: API_HEADERS(),
 body: JSON.stringify(body),
 });
 const json = await res.json();
 return json.result;
}

async function getRecord(table: string, sysId: string): Promise<any> {
 const res = await fetch(`/api/now/table/${table}/${sysId}?sysparm_display_value=all`, {
 headers: API_HEADERS(),
 });
 const json = await res.json();
 return json.result;
}

/* ─── Static responses for non-Bus-Delay options ─── */
function getStaticResponse(message: string): string {
 const lower = message.toLowerCase().trim();

 if (lower === "bus schedule" || lower.includes("schedule")) {
 return "🚌 BUS-12 Schedule:\n• Anna Nagar: 8:00 AM\n• Mogappair: 8:15 AM\n• Ambattur: 8:30 AM\n• RMD College: 8:45 AM\nNext bus arrives in 10 minutes!";
 }
 if (lower === "bus pass status" || lower.includes("pass")) {
 return "✅ Your bus pass is ACTIVE\n\n📋 Pass Details:\n• Pass ID: BP-001\n• Bus: BUS-12\n• Valid Until: March 31, 2027\n• Status: Active\n\nYour pass is valid for 287 more days.";
 }
 if (lower === "track my bus" || lower.includes("track")) {
 return "📍 BUS-12 Current Location:\n\nRoute: Anna Nagar → RMD College\n🟢 Currently at: Mogappair\n⏱ ETA to RMD College: 10 mins\n\nThe bus is running on time!";
 }
 if (lower === "lost & found" || lower.includes("lost") || lower.includes("found")) {
 return "I can help with lost & found items. Would you like to:\n\n1️⃣ Report a lost item\n2️⃣ Report a found item\n3️⃣ Check status of reported items\n\nPlease select an option or describe what you need.";
 }

 return `I understand you're asking about "${message}". Let me help you with that.\n\nFor immediate assistance, try these options:\n• Type 'bus schedule' for timings\n• Type 'track' to locate your bus\n• Type 'pass' for pass info`;
}

/* ─── Main Component ─── */
export default function ChatWidget() {
 const [isOpen, setIsOpen] = useState(false);
 const [messages, setMessages] = useState<Message[]>([
 {
 id: 1,
 text: "Hi! 👋 I'm your MoveSmart transportation assistant. How can I help you today?",
 sender: "bot",
 },
 ]);
 const [inputValue, setInputValue] = useState("");
 const [isTyping, setIsTyping] = useState(false);
 const [busDelay, setBusDelay] = useState<BusDelayState>({
 step: "idle",
 busId: "",
 busLabel: "",
 routeId: "",
 routeLabel: "",
 stopId: "",
 stopLabel: "",
 description: "",
 latitude: "",
 longitude: "",
 });

 const messagesEndRef = useRef<HTMLDivElement>(null);
 const inputRef = useRef<HTMLInputElement>(null);

 useEffect(() => {
 messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
 }, [messages, isTyping]);

 useEffect(() => {
 if (isOpen && inputRef.current) {
 inputRef.current.focus();
 }
 }, [isOpen]);

 /* ─── Add messages helper ─── */
 const addBotMessage = (text: string, extras?: Partial<Message>) => {
 const msg: Message = {
 id: Date.now() + Math.random(),
 text,
 sender: "bot",
 ...extras,
 };
 setMessages((prev) => [...prev, msg]);
 };

 const addUserMessage = (text: string) => {
 const msg: Message = {
 id: Date.now() + Math.random(),
 text,
 sender: "user",
 };
 setMessages((prev) => [...prev, msg]);
 };

 /* ─── Bus Delay Flow ─── */
 const startBusDelayFlow = async () => {
 addUserMessage("Bus Delay");
 setIsTyping(true);
 setBusDelay((s) => ({ ...s, step: "select_bus" }));

 try {
 const buses = await fetchTableRecords("u_bus");
 const options: OptionItem[] = buses.map((b: any) => ({
 label: b.u_bus_number?.display_value || b.u_bus_number || "Unknown",
 value: b.sys_id?.value || b.sys_id,
 }));
 setIsTyping(false);
 addBotMessage("Which bus are you waiting for?", { options });
 } catch {
 setIsTyping(false);
 addBotMessage("Sorry, I couldn't fetch bus data. Please try again later.");
 setBusDelay((s) => ({ ...s, step: "idle" }));
 }
 };

 const handleBusSelected = async (option: OptionItem) => {
 addUserMessage(option.label);
 setBusDelay((s) => ({ ...s, busId: option.value, busLabel: option.label, step: "select_route" }));
 setIsTyping(true);

 try {
 const routes = await fetchTableRecords("u_route");
 const options: OptionItem[] = routes.map((r: any) => ({
 label: `${r.u_route_name?.display_value || r.u_route_name || ""} (${r.u_route_id?.display_value || r.u_route_id || ""})`,
 value: r.sys_id?.value || r.sys_id,
 }));
 setIsTyping(false);
 addBotMessage("Which route is this bus on?", { options });
 } catch {
 setIsTyping(false);
 addBotMessage("Sorry, I couldn't fetch route data. Please try again later.");
 setBusDelay((s) => ({ ...s, step: "idle" }));
 }
 };

 const handleRouteSelected = async (option: OptionItem) => {
 addUserMessage(option.label);
 setBusDelay((s) => ({ ...s, routeId: option.value, routeLabel: option.label, step: "select_stop" }));
 setIsTyping(true);

 try {
 const stops = await fetchTableRecords("u_bus_stop", `u_route_id=${option.value}`);
 const options: OptionItem[] = stops.map((s: any) => ({
 label: `${s.u_stop_name?.display_value || s.u_stop_name || ""} (${s.u_stop_id?.display_value || s.u_stop_id || ""})`,
 value: s.sys_id?.value || s.sys_id,
 }));
 setIsTyping(false);
 if (options.length === 0) {
 addBotMessage("No stops found for this route. Which stop are you at? (type the name)");
 } else {
 addBotMessage("Which bus stop are you waiting at?", { options });
 }
 } catch {
 setIsTyping(false);
 addBotMessage("Sorry, I couldn't fetch bus stop data. Please try again later.");
 setBusDelay((s) => ({ ...s, step: "idle" }));
 }
 };

 const handleStopSelected = (option: OptionItem) => {
 addUserMessage(option.label);
 setBusDelay((s) => ({ ...s, stopId: option.value, stopLabel: option.label, step: "describe" }));
 addBotMessage("Please describe the delay issue (e.g., how long you've been waiting):");
 };

 const handleDescriptionSubmit = (text: string) => {
 addUserMessage(text);
 setBusDelay((s) => ({ ...s, description: text, step: "location" }));
 addBotMessage("I need your location to calculate the bus ETA. Please share your location:", { locationBtn: true });
 };

 const handleLocationShare = async () => {
 addUserMessage("📍 Location shared");
 let lat = "13.0";
 let lng = "80.2";

 // Try browser geolocation, fallback to default
 if (navigator.geolocation) {
 try {
 const pos = await new Promise<GeolocationPosition>((resolve, reject) => {
 navigator.geolocation.getCurrentPosition(resolve, reject, { timeout: 5000 });
 });
 lat = pos.coords.latitude.toFixed(4);
 lng = pos.coords.longitude.toFixed(4);
 } catch {
 // Use defaults
 }
 }

 setBusDelay((s) => ({ ...s, latitude: lat, longitude: lng, step: "submitting" }));
 addBotMessage(`📍 Location received (${lat}, ${lng}). Creating your bus delay report...`);
 setIsTyping(true);

 // Create transportation case
 try {
 const record = await createRecord("u_transportation_case", {
 u_issue_type: "Bus Delay",
 u_bus_number: busDelay.busId,
 u_route_id: busDelay.routeId,
 u_bus_stop: busDelay.stopId,
 u_reported_latitude: lat,
 u_reported_longitude: lng,
 u_description: busDelay.description,
 u_short_description: "Bus Delay Report",
 });

 const sysId = record?.sys_id?.value || record?.sys_id;
 if (!sysId) {
 throw new Error("No sys_id returned");
 }

 // Poll for solution_response (business rule runs AFTER insert)
 let etaResponse = "";
 let caseNumber = record?.u_case_number?.display_value || record?.u_case_number || "";

 // Wait and poll up to 3 times
 for (let attempt = 0; attempt < 4; attempt++) {
 await new Promise((resolve) => setTimeout(resolve, 2000));
 const updated = await getRecord("u_transportation_case", sysId);
 const solution = updated?.u_solution_response?.display_value || updated?.u_solution_response || "";
 caseNumber = updated?.u_case_number?.display_value || updated?.u_case_number || caseNumber;
 if (solution) {
 etaResponse = solution;
 break;
 }
 }

 setIsTyping(false);

 if (etaResponse) {
 addBotMessage("✅ Your bus delay report has been filed! Here's the ETA information:", {
 resultCard: {
 caseNumber,
 etaResponse,
 bus: busDelay.busLabel,
 route: busDelay.routeLabel,
 stop: busDelay.stopLabel,
 },
 });
 } else {
 addBotMessage(`✅ Your bus delay report has been filed as ${caseNumber || "a new case"}. The ETA is being calculated — check back shortly for the solution response.`);
 }

 setBusDelay({
 step: "result",
 busId: "",
 busLabel: "",
 routeId: "",
 routeLabel: "",
 stopId: "",
 stopLabel: "",
 description: "",
 latitude: "",
 longitude: "",
 });
 } catch (err) {
 setIsTyping(false);
 addBotMessage("❌ Sorry, I couldn't create the bus delay report. Please try again or contact support.");
 setBusDelay((s) => ({ ...s, step: "idle" }));
 }
 };

 /* ─── Handle general send ─── */
 const sendMessage = (text: string) => {
 if (!text.trim()) return;
 const trimmed = text.trim();

 // If in Bus Delay flow — handle step-specific input
 if (busDelay.step === "describe") {
 handleDescriptionSubmit(trimmed);
 setInputValue("");
 return;
 }

 if (busDelay.step === "select_stop" && trimmed) {
 // User typed a stop name manually
 addUserMessage(trimmed);
 setBusDelay((s) => ({ ...s, stopId: "", stopLabel: trimmed, step: "describe" }));
 addBotMessage("Please describe the delay issue (e.g., how long you've been waiting):");
 setInputValue("");
 return;
 }

 // Start Bus Delay flow
 if (trimmed.toLowerCase() === "bus delay") {
 setInputValue("");
 startBusDelayFlow();
 return;
 }

 // Static responses for other options
 addUserMessage(trimmed);
 setInputValue("");
 setIsTyping(true);

 setTimeout(() => {
 setIsTyping(false);
 addBotMessage(getStaticResponse(trimmed));
 }, 800);
 };

 const handleSubmit = (e: React.FormEvent) => {
 e.preventDefault();
 sendMessage(inputValue);
 };

 const handleSuggestionClick = (suggestion: string) => {
 if (suggestion === "Bus Delay") {
 startBusDelayFlow();
 } else {
 sendMessage(suggestion);
 }
 };

 const handleOptionClick = (option: OptionItem) => {
 if (busDelay.step === "select_bus") {
 handleBusSelected(option);
 } else if (busDelay.step === "select_route") {
 handleRouteSelected(option);
 } else if (busDelay.step === "select_stop") {
 handleStopSelected(option);
 }
 };

 /* ─── Format text ─── */
 const formatMessage = (text: string) => {
 return text.split("\n").map((line, i) => (
 <span key={i}>
 {line}
 {i < text.split("\n").length - 1 && <br />}
 </span>
 ));
 };

 /* ─── Check if input should be disabled ─── */
 const isInputDisabled = isTyping || busDelay.step === "submitting" || busDelay.step === "location" || busDelay.step === "select_bus" || busDelay.step === "select_route";

 return (
 <>
 {/* Floating Action Button */}
 {!isOpen && (
 <button
 className="ms-chat-fab"
 onClick={() => setIsOpen(true)}
 aria-label="Open chat assistant"
 >
 <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
 </svg>
 <span className="ms-chat-fab-pulse"></span>
 </button>
 )}

 {/* Chat Panel */}
 {isOpen && (
 <div className="ms-chat-panel">
 {/* Header */}
 <div className="ms-chat-header">
 <div className="ms-chat-header-left">
 <div className="ms-chat-avatar">
 <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <rect x="3" y="11" width="18" height="10" rx="2" />
 <circle cx="12" cy="5" r="2" />
 <path d="M12 7v4" />
 <line x1="8" y1="16" x2="8" y2="16" />
 <line x1="16" y1="16" x2="16" y2="16" />
 </svg>
 </div>
 <div className="ms-chat-header-info">
 <span className="ms-chat-header-title">MoveSmart Assistant</span>
 <span className="ms-chat-header-status">Online</span>
 </div>
 </div>
 <button
 className="ms-chat-close-btn"
 onClick={() => setIsOpen(false)}
 aria-label="Close chat"
 >
 <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <line x1="18" y1="6" x2="6" y2="18" />
 <line x1="6" y1="6" x2="18" y2="18" />
 </svg>
 </button>
 </div>

 {/* Messages */}
 <div className="ms-chat-messages">
 {messages.map((msg) => (
 <div key={msg.id}>
 <div
 className={
 msg.sender === "bot"
 ? "ms-chat-message ms-chat-message-bot"
 : "ms-chat-message ms-chat-message-user"
 }
 >
 <div className="ms-chat-bubble">
 {formatMessage(msg.text)}
 </div>
 </div>

 {/* Render interactive options */}
 {msg.options && msg.options.length > 0 && (
 <div className="ms-chat-options">
 {msg.options.map((opt) => (
 <button
 key={opt.value}
 className="ms-chat-option-btn"
 onClick={() => handleOptionClick(opt)}
 disabled={
 busDelay.step !== "select_bus" &&
 busDelay.step !== "select_route" &&
 busDelay.step !== "select_stop"
 }
 >
 {opt.label}
 </button>
 ))}
 </div>
 )}

 {/* Location share button */}
 {msg.locationBtn && (
 <div className="ms-chat-options">
 <button
 className="ms-chat-location-btn"
 onClick={handleLocationShare}
 disabled={busDelay.step !== "location"}
 >
 <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" />
 <circle cx="12" cy="10" r="3" />
 </svg>
 Share My Location
 </button>
 </div>
 )}

 {/* ETA Result Card */}
 {msg.resultCard && (
 <div className="ms-chat-result-card">
 <div className="ms-result-card-header">
 <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <circle cx="12" cy="12" r="10" />
 <polyline points="12 6 12 12 16 14" />
 </svg>
 <span className="ms-result-card-title">ETA Result</span>
 <span className="ms-result-card-case">{msg.resultCard.caseNumber}</span>
 </div>
 <div className="ms-result-card-body">
 <p className="ms-result-card-eta">{msg.resultCard.etaResponse}</p>
 </div>
 <div className="ms-result-card-footer">
 <div className="ms-result-card-detail">
 <span className="ms-result-detail-label">Bus</span>
 <span className="ms-result-detail-value">{msg.resultCard.bus}</span>
 </div>
 <div className="ms-result-card-detail">
 <span className="ms-result-detail-label">Route</span>
 <span className="ms-result-detail-value">{msg.resultCard.route}</span>
 </div>
 <div className="ms-result-card-detail">
 <span className="ms-result-detail-label">Stop</span>
 <span className="ms-result-detail-value">{msg.resultCard.stop}</span>
 </div>
 </div>
 </div>
 )}
 </div>
 ))}

 {/* Typing Indicator */}
 {isTyping && (
 <div className="ms-chat-message ms-chat-message-bot">
 <div className="ms-chat-bubble ms-chat-typing">
 <span className="ms-typing-dot"></span>
 <span className="ms-typing-dot"></span>
 <span className="ms-typing-dot"></span>
 </div>
 </div>
 )}

 {/* Suggestions (show only if welcome message and idle) */}
 {messages.length === 1 && !isTyping && busDelay.step === "idle" && (
 <div className="ms-chat-suggestions">
 {SUGGESTIONS.map((s) => (
 <button
 key={s}
 className="ms-chat-suggestion-chip"
 onClick={() => handleSuggestionClick(s)}
 >
 {s}
 </button>
 ))}
 </div>
 )}

 <div ref={messagesEndRef} />
 </div>

 {/* Input Area */}
 <form className="ms-chat-input-area" onSubmit={handleSubmit}>
 <input
 ref={inputRef}
 type="text"
 className="ms-chat-input"
 placeholder={
 busDelay.step === "describe"
 ? "Describe the delay..."
 : busDelay.step === "location"
 ? "Use the location button above"
 : "Type a message..."
 }
 value={inputValue}
 onChange={(e) => setInputValue(e.target.value)}
 disabled={isInputDisabled}
 />
 <button
 type="submit"
 className="ms-chat-send-btn"
 disabled={!inputValue.trim() || isInputDisabled}
 aria-label="Send message"
 >
 <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <line x1="22" y1="2" x2="11" y2="13" />
 <polygon points="22 2 15 22 11 13 2 9 22 2" />
 </svg>
 </button>
 </form>
 </div>
 )}
 </>
 );
}
","import React, { useState, useEffect, useCallback } from "react";
import "./styles.css";
import HomeScreen from "./components/HomeScreen";
import ReportIssueScreen from "./components/ReportIssueScreen";
import IssueFormScreen from "./components/IssueFormScreen";
import MyBusScreen from "./components/MyBusScreen";
import BusPassScreen from "./components/BusPassScreen";
import MyRequestsScreen from "./components/MyRequestsScreen";
import RequestDetailScreen from "./components/RequestDetailScreen";
import LostFoundScreen from "./components/LostFoundScreen";
import EmergencyScreen from "./components/EmergencyScreen";
import ProfileScreen from "./components/ProfileScreen";
import BottomNav from "./components/BottomNav";
import ChatWidget from "./components/ChatWidget";

interface ViewState {
 view: string;
 type: string | null;
 id: string | null;
}

function getViewFromUrl(): ViewState {
 const params = new URLSearchParams(window.location.search);
 return {
 view: params.get("view") || "home",
 type: params.get("type") || null,
 id: params.get("id") || null,
 };
}

export default function App() {
 const [currentView, setCurrentView] = useState<ViewState>(getViewFromUrl);

 useEffect(() => {
 const onPopState = () => setCurrentView(getViewFromUrl());
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 const navigate = useCallback(
 (viewName: string, extras?: { type?: string; id?: string }) => {
 const params = new URLSearchParams({ view: viewName });
 if (extras?.type) params.set("type", extras.type);
 if (extras?.id) params.set("id", extras.id);
 const path = `${window.location.pathname}?${params}`;
 window.history.pushState({}, "", path);
 setCurrentView({
 view: viewName,
 type: extras?.type || null,
 id: extras?.id || null,
 });
 },
 []
 );

 const { view, type, id } = currentView;

 const renderScreen = () => {
 switch (view) {
 case "home":
 return <HomeScreen navigate={navigate} />;
 case "report":
 return <ReportIssueScreen navigate={navigate} />;
 case "issue-form":
 return <IssueFormScreen navigate={navigate} issueType={type} />;
 case "mybus":
 return <MyBusScreen navigate={navigate} />;
 case "buspass":
 return <BusPassScreen navigate={navigate} />;
 case "requests":
 return <MyRequestsScreen navigate={navigate} />;
 case "request-detail":
 return <RequestDetailScreen navigate={navigate} requestId={id} />;
 case "lostfound":
 return <LostFoundScreen navigate={navigate} />;
 case "emergency":
 return <EmergencyScreen navigate={navigate} />;
 case "profile":
 return <ProfileScreen navigate={navigate} />;
 default:
 return <HomeScreen navigate={navigate} />;
 }
 };

 return (
 <div className="ms-app">
 <div className="ms-content">{renderScreen()}</div>
 <BottomNav currentView={view} navigate={navigate} />
 <ChatWidget />
 </div>
 );
}
